#pragma once

// The optimization adapter of functional structures (RES-FUNC-012): the
// structure's settable parameters are design variables (bound parameters as
// the framework's scene bindings, free ones as parameter/<id>), its analysis
// metrics and its constraint values (constraint.<id>) are quantities. The
// candidates are generated by the existing algorithms; each is evaluated by
// the structure's analysis on its own copy of the design.

#include "foundation/Result.h"

#include <nlohmann/json.hpp>

#include <memory>

namespace resonant::optimization {
class AdapterRegistry;
class DesignEvaluator;
}  // namespace resonant::optimization

namespace resonant::coupling {

inline constexpr const char* kFunctionalAdapterId = "functional";

// configuration: {"structure": "<id>", "model": "<model id>" (optional)}
Result<std::shared_ptr<const optimization::DesignEvaluator>> bindFunctionalAdapter(const nlohmann::json& snapshot, const nlohmann::json& configuration);
void registerFunctionalOptimization(optimization::AdapterRegistry& registry);

}  // namespace resonant::coupling
